// hasFieldChanged checks if a field value has changed from oldValues
func (t *FAPostingGroup) hasFieldChanged(fieldName string) bool {
	return fAPostingGroupFields.Changed(t.fieldRef, t.oldValues, fieldName)
}

// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *FAPostingGroup) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *FAPostingGroup) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"code": {{"FA_Allocation", false, "code", "", 0}, {"FA_Depreciation_Book", false, "fa_posting_group", "", 0}, {"FA_Journal_Line", false, "fa_posting_group", "", 0}, {"FA_Ledger_Entry", false, "fa_posting_group", "", 0}, {"Maintenance_Ledger_Entry", false, "fa_posting_group", "", 0}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

// refuseDeleteWhenUsed: a record still refers to this one
func (t *FAPostingGroup) refuseDeleteWhenUsed() error {
	return tables.RefuseDeleteWhenUsed(t.exec(), t.dbType, tables.DeletedRecord{
		Table: FAPostingGroupTableName, Global: false, Company: t.company,
		KeyColumn: "code", Key: t.Code, KeyText: fmt.Sprint(t.Code),
	}, []tables.Reference{
		{Table: "FA_Allocation", Column: "code"},
		{Table: "FA_Depreciation_Book", Column: "fa_posting_group"},
		{Table: "FA_Journal_Line", Column: "fa_posting_group"},
		{Table: "FA_Ledger_Entry", Column: "fa_posting_group"},
		{Table: "Maintenance_Ledger_Entry", Column: "fa_posting_group"},
	})
}

// Delete removes the record from the database
func (t *FAPostingGroup) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
		// Refused while a record still refers to this one (refuse_delete_when_used)
		if t.temp == nil {
			if err := t.refuseDeleteWhenUsed(); err != nil {
				t.triggerErr = err
				return false
			}
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FAPostingGroupTableName)

	// Collect arguments for DELETE
	args := []interface{}{
		t.Code,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`DELETE FROM "%s" WHERE 1=1 AND code = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	_, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete FA_Posting_Group: %v\n", err)
		return false
	}
	return true
}

